export function builtinSupport(name) {
  if(name==='suspend')return {kind:'limited',label:'LIMITED · BOUNDED SUSPENSION',text:'Waits at most five seconds per call, then replenishes tick/time allowances. Maximum 100 suspensions and 15 seconds total in the editor. Output/allocation limits remain cumulative. No indefinite wait or resume().'};
  if(['value_bytes','object_bytes'].includes(name))return {kind:'stub',label:'STUB · FIXED ZERO',text:'Always returns 0 here. This is not a memory measurement. object_bytes still checks that its object exists.'};
  if(['reseed_random','sqlite_interrupt'].includes(name))return {kind:'stub',label:'LIMITED · NO-OP',text:name==='reseed_random'?'Returns 0 without seeding a generator; random calls use fresh Web Crypto entropy.':'Validates a handle and returns 0 between synchronous queries. It cannot interrupt an active query; use Stop to terminate a worker.'};
  if(['curl','exec','getenv','spellcheck','open_network_connection'].includes(name))return {kind:'mocked',label:'MOCKED · CONFIGURED RESPONSE',text:'Matches the exact request against prepared fixtures. No real network, process, environment or dictionary access occurs. Missing fixtures raise E_INVARG. The lesson checkpoint supplies the request used below.'};
  if(name.startsWith('file_'))return {kind:'simulated',label:'SIMULATED · VIRTUAL FILESYSTEM',text:'Files and handles live in this path’s saved world, not your computer. Permissions are metadata and timestamps are logical counters. Load the lesson checkpoint for /lesson and handle 1; these can change after earlier experiments.'};
  if(name.startsWith('sqlite_'))return {kind:'limited',label:'LIMITED · REAL SQLITE',text:'Uses real SQLite with bounded single-table queries. No joins, transactions, triggers or extensions. Data persists in this world; the lesson checkpoint supplies open handle 1. Engine errors return strings; argument and quota errors raise diagnostics.'};
  if(/^(connection_|connected_|idle_seconds|boot_player|buffered_output_length|output_delimiters|force_input|flush_input|switch_player|read$|read_http|listen$|unlisten$|listeners$)/.test(name))return {kind:'simulated',label:'SIMULATED · CONNECTIONS',text:'Virtual connections and listeners only: no live socket or player. Input/output queues persist in this world. Ages count operations, and blocking read with no input cannot suspend. The checkpoint supplies a learner connection and any required input.'};
  if(['server_version','server_log','shutdown','dump_database','db_disk_size','load_server_options'].includes(name))return {kind:'simulated',label:'SIMULATED · SERVER ADMINISTRATION',text:'Operates on the saved educational host. shutdown records a request without stopping the app; logs and checkpoints stay in the world. server_version is a fixed educational version string. Only fg_ticks/fg_seconds server options are supported.'};
  if(['crypt','salt'].includes(name))return {kind:'limited',label:'LIMITED · TRADITIONAL DES',text:'Only traditional DES crypt/salt formats are supported. This legacy algorithm is unsuitable for password storage; modular crypt formats are rejected.'};
  if(['argon2','argon2_verify'].includes(name))return {kind:'limited',label:'LIMITED · BOUNDED ARGON2ID',text:'A real Argon2id implementation with capped resources. Example parameters are deliberately small for demonstration, not production password-storage settings.'};
  if(['match','rmatch','substitute','pcre_match','pcre_replace'].includes(name))return {kind:'limited',label:'LIMITED · REGEX SUBSET',text:'Uses a bounded RE2-compatible engine. Backreferences in patterns, lookarounds and unsupported syntax are rejected. Native MOO/PCRE patterns may need changes.'};
  if(['set_task_perms','task_perms','caller_perms','set_player_flag','property_info','set_property_info','verb_info','set_verb_info','create','move'].includes(name))return {kind:'limited',label:'LIMITED · SERVER PERMISSIONS',text:'Metadata and selected identity checks are modeled, but general MOO permission enforcement is absent. A successful operation here does not prove authorization on a real server.'};
  if(['time','ctime','ftime','ticks_left','seconds_left','task_id','task_local','set_task_local','callers'].includes(name))return {kind:'limited',label:'EDUCATIONAL RUNTIME',text:'Time/budget/task values describe this execution. ctime uses UTC; ticks count evaluator steps. Task-local values last for one run. Bounded suspend(seconds) is available in workers; no multi-task scheduler, fork or resume is available.'};
  if(['parse_json','generate_json','floatstr','parse_ansi','remove_ansi'].includes(name))return {kind:'limited',label:'LIMITED · FORMAT SUBSET',text:'The supported options and type mappings are listed in Quick Reference. JSON booleans become integers and null becomes E_NONE; ANSI operations use tagged strings rather than a terminal emulator.'};
  return undefined;
}
